import { apiClient } from './api';
import type { ApiResponse } from '../types/common.types';

/**
 * Reports and dashboard analytics (REP-001..REP-008). Every figure, table and
 * file comes from the server: results are paginated server-side and exports
 * are generated by the server from the same filters as the on-screen result.
 */

export type ReportColumnType = 'text' | 'int' | 'money' | 'date' | 'datetime';
export interface ReportColumn {
  key: string;
  label: string;
  type: ReportColumnType;
}
export interface ReportDefinition {
  code: string;
  title: string;
  description: string;
  dateField: string;
  hasStatus: boolean;
  searchHint: string | null;
  paginated: boolean;
  columns: ReportColumn[];
}
export interface ReportFilters {
  from?: string;
  to?: string;
  status?: string;
  search?: string;
  /** Comma-separated column keys to include (custom report fields); all when absent. */
  columns?: string;
}
export interface ReportPageResult {
  rows: Record<string, unknown>[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}
export type ExportFormat = 'csv' | 'xlsx' | 'pdf';

export interface CountAmount {
  count: number;
  amount: number;
}
export interface StatusLine extends CountAmount {
  status: string;
}
export interface FinancialSummary {
  from: string;
  to: string;
  revenue: {
    gatewaySuccessful: CountAmount;
    manualVerified: CountAmount;
    totalCollected: number;
    gatewayNotCounted: StatusLine[];
    manualNotCounted: StatusLine[];
  };
  refunds: { requested: CountAmount; pending: CountAmount; approved: CountAmount; completed: CountAmount };
  discounts: { enrollmentDiscounts: CountAmount; couponRedemptions: StatusLine[] };
  scholarships: { awards: StatusLine[] };
  expenses: {
    byCurrency: Array<{ currency: string; count: number; amount: number }>;
    byCategory: Array<{ category: string; currency: string; count: number; amount: number }>;
    withApprover: CountAmount;
  };
}
export interface DashboardAnalytics {
  from: string;
  to: string;
  months: Array<{ month: string; registrations: number; enrollments: number; revenueCollected: number }>;
  enrollmentsByStatus: Array<{ status: string; count: number }>;
  attendanceByBatch: Array<{ batchCode: string; batchName: string; byStatus: Record<string, number>; marked: number }>;
  assessmentsByStatus: Array<{ status: string; count: number }>;
  placementApplicationsByStatus: Array<{ status: string; count: number }>;
  accountsByRole: Array<{ role: string; status: string; count: number }>;
}

/** The server's error text (details included), also when the error body arrived as a Blob. */
async function errorText(err: any, fallback: string): Promise<string> {
  let body = err?.response?.data;
  if (body instanceof Blob) {
    try {
      body = JSON.parse(await body.text());
    } catch {
      body = null;
    }
  }
  const details: { field?: string; message?: string }[] = Array.isArray(body?.details) ? body.details : [];
  const detailText = details.map((d) => (d.field ? `${d.field}: ${d.message}` : d.message)).filter(Boolean).join('; ');
  const base = body?.message || err?.message || fallback;
  return detailText && !base.includes(detailText) ? `${base} (${detailText})` : base;
}

async function call<T>(request: () => Promise<{ data?: { data?: T } }>, empty: T, fallback: string): Promise<ApiResponse<T>> {
  try {
    const res = await request();
    return { success: true, data: (res.data?.data ?? empty) as T };
  } catch (err) {
    return { success: false, data: empty, error: await errorText(err, fallback) };
  }
}

/** Only the filters that are set; the same object drives the table and the export. */
const params = (f: ReportFilters) => Object.fromEntries(Object.entries(f).filter(([, v]) => v !== undefined && v !== ''));

export const reportsService = {
  getCatalog: () => call<ReportDefinition[]>(() => apiClient.get('/admin/reports/catalog'), [], 'Reports could not be loaded.'),

  getStatuses: (code: string) => call<string[]>(() => apiClient.get(`/admin/reports/${code}/statuses`), [], 'Status values could not be loaded.'),

  runReport: (code: string, filters: ReportFilters, page: number, pageSize: number) =>
    call<ReportPageResult | null>(
      () => apiClient.get(`/admin/reports/${code}`, { params: { ...params(filters), page, pageSize } }),
      null,
      'The report could not be generated.'
    ),

  getFinancialSummary: (range: { from?: string; to?: string }) =>
    call<{ summary: FinancialSummary; rows: Record<string, unknown>[]; columns: ReportColumn[] } | null>(
      () => apiClient.get('/admin/reports/financial-summary', { params: params(range) }),
      null,
      'The financial summary could not be generated.'
    ),

  getAnalytics: (range: { from?: string; to?: string }) =>
    call<DashboardAnalytics | null>(() => apiClient.get('/admin/reports/analytics', { params: params(range) }), null, 'Dashboard analytics could not be loaded.'),

  /** Downloads the file the server generated (genuine CSV, XLSX or PDF). */
  async exportReport(code: string, format: ExportFormat, filters: ReportFilters): Promise<ApiResponse<{ fileName: string; rows: number } | null>> {
    try {
      const res = await apiClient.get(`/admin/reports/${code}/export`, { params: { ...params(filters), format }, responseType: 'blob' });
      const disposition = String(res.headers['content-disposition'] || '');
      const fileName = /filename="([^"]+)"/.exec(disposition)?.[1] || `${code}.${format}`;
      const url = URL.createObjectURL(res.data as Blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      return { success: true, data: { fileName, rows: Number(res.headers['x-report-row-count'] ?? 0) } };
    } catch (err) {
      return { success: false, data: null, error: await errorText(err, 'The export could not be generated.') };
    }
  },
};
